package com.justdataplease.boringtravel.ui.icons

import androidx.compose.ui.graphics.vector.VectorGroup
import androidx.compose.ui.graphics.vector.VectorPath
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/** The own icon set (generated by tools/icons/icons.py) builds, has its drawables, and replaced Material icons. */
class BtIconsTest {
    private val icons by lazy { BtIcons.all() }

    @Test fun everyIconBuilds() {
        assertTrue("expected the full set, got ${icons.size}", icons.size >= 70)
        icons.forEach { (name, icon) ->
            assertEquals("BtIcons.$name", icon.name)
            assertEquals(24f, icon.viewportWidth)
            assertEquals(24f, icon.viewportHeight)
            val paths = icon.root.filterIsInstance<VectorPath>() + icon.root.filterIsInstance<VectorGroup>().flatMap { g -> g.filterIsInstance<VectorPath>() }
            assertTrue("$name has no path", paths.isNotEmpty())
            paths.forEach { path ->
                assertTrue("$name has empty path data", path.pathData.size > 1)
                if (path.stroke != null) assertEquals("$name stroke width", BtIcons.STROKE, path.strokeLineWidth)
                assertTrue("$name draws nothing", path.stroke != null || path.fill != null)
            }
        }
    }

    @Test fun iconsAreCached() {
        assertTrue(BtIcons.Add === BtIcons.Add)
        assertTrue(BtIcons.Trips === icons.getValue("Trips"))
    }

    @Test fun filledStatesAreFilled() {
        listOf(BtIcons.CheckBox, BtIcons.Bookmarked).forEach { icon ->
            assertTrue(icon.name, icon.root.filterIsInstance<VectorPath>().all { it.fill != null })
        }
        listOf(BtIcons.CheckBoxEmpty, BtIcons.Bookmark).forEach { icon ->
            assertTrue(icon.name, icon.root.filterIsInstance<VectorPath>().all { it.fill == null })
        }
    }

    @Test fun everyIconHasItsDrawable() {
        val drawables = File("src/main/res/drawable")
        icons.keys.forEach { name ->
            val file = File(drawables, "bt_ic_" + name.replace(Regex("(?<!^)(?=[A-Z])"), "_").lowercase() + ".xml")
            assertTrue("missing ${file.name}", file.exists())
            assertTrue("${file.name} is not from the generator", file.readText().contains("BtIcons.$name"))
        }
    }

    @Test fun noMaterialIconsInTheApp() {
        val offenders = File("src/main/java").walkTopDown()
            .filter { it.isFile && it.extension == "kt" }
            .filter { it.readText().contains("androidx.compose.material.icons") || MATERIAL_USE.containsMatchIn(it.readText()) }
            .map { it.path }
            .toList()
        assertTrue("Material icons still used (run tools/icons/replace_material.py): $offenders", offenders.isEmpty())
    }

    private companion object {
        val MATERIAL_USE = Regex("""\bIcons\.(AutoMirrored\.)?(Outlined|Filled|Rounded|Sharp|TwoTone|Default)\.""")
    }
}
